// ---------------------------------------------------------------------------
// Document checklist - vocabulary and shipped default rules (W5-01 / BRD DOC-01).
//
// Source of truth: the Phase-1 BRD, "Document checklist": the checklist a
// submission carries is generated by the opportunity's type, stage and flags,
// and each item is mandatory, conditional or optional. The list must be
// admin-maintainable without code, and it must update as the answers change.
//
// This module holds the hand-authored vocabulary and the shipped default item
// rules. Each item points at a catalogue artefact (server/config/memoDocumentList.js)
// so the checklist, the gate and the memo name the same documents, and carries a
// tier plus an applicability rule. The pure evaluation, validation and revision
// logic lives in server/config/documentChecklist.js; storage and HTTP routes live
// in server/checklist.js.
//
// The shipped defaults reproduce the standing MVP document gate (business plan,
// financials and cap table are mandatory) so nothing new blocks a submission
// until an administrator deliberately changes the checklist. The conditional
// items (budget confirmation off-budget, compliance screen when related-party)
// are offered and become due only when their flag trips.
// ---------------------------------------------------------------------------

export const DOCUMENT_CHECKLIST_VERSION = 'CL-01.1';
export const DOCUMENT_CHECKLIST_CONFIG_KEY = 'document_checklist_config';
export const DOCUMENT_CHECKLIST_DEFAULT_REVISION = 1;
export const DOCUMENT_CHECKLIST_VERSION_PREFIX = 'CL-01.';

// The three tiers (BRD DOC-01).
export const CHECKLIST_TIERS = ['mandatory', 'conditional', 'optional'];

// The applicability-rule keys an item may carry. A rule with no keys applies to
// every opportunity; a rule with keys applies only when all of them are met.
export const CHECKLIST_RULE_KEYS = [
  'types', 'exclude_types', 'greenfield_stages', 'exclude_greenfield_stages',
  'off_budget', 'in_budget', 'related_party', 'cross_border',
  'min_commitment_aed', 'max_commitment_aed',
];

// The shipped per-artefact tier and rule. Artefacts not named here inherit the
// memo list's gate flag: a gate artefact is mandatory, the rest optional.
export const DOCUMENT_CHECKLIST_RULES = {
  business_plan: { tier: 'mandatory', exclude_greenfield_stages: ['concept'], enforce: true },
  financials: { tier: 'mandatory', exclude_greenfield_stages: ['concept'], enforce: true },
  cap_table: { tier: 'mandatory', exclude_greenfield_stages: ['concept'], enforce: true },
  budget_confirmation: { tier: 'conditional', off_budget: true, enforce: true },
  compliance_screen: { tier: 'conditional', related_party: true, enforce: false },
  returns_model: { tier: 'optional' },
  valuation_basis: { tier: 'optional' },
  market_data: { tier: 'optional' },
  synergy_case: { tier: 'optional' },
  accretion_statement: { tier: 'optional' },
  funding_plan: { tier: 'optional' },
  risk_register: { tier: 'optional' },
  execution_plan: { tier: 'optional' },
  gate_checklist: { tier: 'optional' },
  due_diligence_report: { tier: 'optional' },
};

export const DOCUMENT_CHECKLIST_DISCLAIMER =
  'The checklist is generated from the opportunity type, stage and flags. Mandatory and due-conditional items block submission; optional items are collected but never block. Administrators edit the checklist without code; each save mints a new revision.';

export default {
  DOCUMENT_CHECKLIST_VERSION, DOCUMENT_CHECKLIST_CONFIG_KEY, DOCUMENT_CHECKLIST_DEFAULT_REVISION,
  DOCUMENT_CHECKLIST_VERSION_PREFIX, CHECKLIST_TIERS, CHECKLIST_RULE_KEYS,
  DOCUMENT_CHECKLIST_RULES, DOCUMENT_CHECKLIST_DISCLAIMER,
};
